-- Dustwallow Marsh: creature abilities
-- Most of the zone's creatures (the Grimtotem, the Black Dragonflight, the Defias and Bluefen, the Theramore deserters, the spiders, raptors and crocolisks) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '4323,4324,4329,4331,4339,4341,4343,4344,4345,4346,4347,4348,4356,4357,4359,4361,4362,4363,4364,4366,4368,4370,4371,4374,4376,4378,4379,4380,4385,4389,4390,4393,4394,4397,4401,4403,4404,4414,4834,4841,4922,4923,4966,4967,4979,5057,5091,5092,5093,5094,5184,5434,10036,10321,14230,14231,14233,14234,14235,14237,15552,16072,23589,23590,23591,23592,23594,23595,23636,23637,23679,23687,23714,23841,23873,23899,23900,23941,23949,23951,24841,24842,38006,44390,45227,48130';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '4973,14881,48131,51924';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
